// Generated by `mix ex_tauri.ios init` (ex_tauri:ios-runtime); rerunning it
// regenerates this file.
fn main() {
  link_erlang_runtime();
  tauri_build::build()
}

// On iOS the BEAM runs inside the app (src/lib.rs): ERTS is linked in from the
// liberlang.xcframework `mix ex_tauri.ios run|device` stages beside the release
// (`ampoule pack --target ios`), and `ex_tauri_in_process` turns on the code
// that starts it. Found by path: Xcode's "Build Rust Code" phase does not pass
// the shell's environment on to cargo.
fn link_erlang_runtime() {
  println!("cargo::rustc-check-cfg=cfg(ex_tauri_in_process)");

  let target = std::env::var("TARGET").unwrap_or_default();
  if !target.contains("apple-ios") {
    return;
  }

  let framework = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../_build/ex_tauri_ios/liberlang.xcframework");
  println!("cargo:rerun-if-changed={}", framework.display());
  if !framework.exists() {
    return;
  }

  let slice = if target.ends_with("-sim") { "ios-arm64-simulator" } else { "ios-arm64" };
  let dir = framework.join(slice);
  if !dir.join("liberlang.a").exists() {
    panic!("{} has no {slice}/liberlang.a", framework.display());
  }

  println!("cargo:rerun-if-changed={}", dir.join("liberlang.a").display());
  println!("cargo:rustc-link-search=native={}", dir.display());
  println!("cargo:rustc-link-lib=static=erlang");
  println!("cargo:rustc-link-lib=c++");
  println!("cargo:rustc-cfg=ex_tauri_in_process");
}
